desktopCSS:
/* ==================== DESKTOP ==================== */
@media (min-width: 1280px) {
  .header-row {
    position: static;
    background: transparent;
    box-shadow: none;
    height: auto;           
    min-height: 100px;       
    padding-top: 90px;      
    padding-left: 12%;      
    padding-right: 12%;     
    margin-bottom: 0px;    
    justify-content: space-between;
    pointer-events: auto;
  }

  .title-group { 
    padding-left: 0; 
    padding-right: 0;
  }

  .title { 
    font-size: 36px;           
    font-weight: 700;          
    color: #f8fafc;            
    margin: 0 0 8px 0;
  }

  .subtitle { 
    font-size: 24px;           
    color: #67e8f9; 
    font-weight: 600;
    display: block;
    margin-bottom: 6px;
  }

  .sources {
    font-size: 15px;         
    color: #94a3b8;
    display: block;
  }

  .actions {
    position: static !important;
    flex-direction: row !important;
    gap: 12px !important;
    align-items: center !important;
  }

  #full-capture-area {
    padding: 15px;
  }

  .chart-container {
    padding-bottom: 60px;
  }

  .chart-container img {
    max-width: 90%;
    max-height: 100%;
  }
}
